import{_ as a,o as i,c as t,a3 as n}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Explanation: Automatically Balanced Production Lines and Adaptive Devices","description":"","frontmatter":{"translationSource":{"title":"讲解：自配平产线和自适应装置","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=MSyCxO1yMtqlXdUCG6Utsc","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/explanation-automatically-balanced-production-lines-and-adaptive-devices"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/explanation-automatically-balanced-production-lines-and-adaptive-devices"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/explanation-automatically-balanced-production-lines-and-adaptive-devices"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/explanation-automatically-balanced-production-lines-and-adaptive-devices"}]]},"headers":[],"relativePath":"explanation-automatically-balanced-production-lines-and-adaptive-devices.md","filePath":"logistics/src/page-MSyCxO1yMtqlXdUCG6Utsc.md"}'),r={name:"explanation-automatically-balanced-production-lines-and-adaptive-devices.md"};function s(o,e,l,p,u,c){return i(),t("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><h1 id="explanation-automatically-balanced-production-lines-and-adaptive-devices" tabindex="-1">Explanation: Automatically Balanced Production Lines and Adaptive Devices <a class="header-anchor" href="#explanation-automatically-balanced-production-lines-and-adaptive-devices" aria-label="Permalink to &quot;Explanation: Automatically Balanced Production Lines and Adaptive Devices&quot;">​</a></h1><blockquote><p>Source page ID: <code>MSyCxO1yMtqlXdUCG6Utsc</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=MSyCxO1yMtqlXdUCG6Utsc" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>This page currently serves as video copy/a script.</p><p><span id="source-block-TpyJfHRw0zbnYOTULA9OaX"></span></p><h2 id="preview-of-materials" tabindex="-1">Preview of Materials <a class="header-anchor" href="#preview-of-materials" aria-label="Permalink to &quot;Preview of Materials&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-403d77df278b7ae4.q90-d1663eb5e22f9e26.webp" alt="Explanation: Automatically Balanced Production Lines and Adaptive Devices"></p><div class="logistics-image-caption" data-source-block="kHsqAVmcDeYRDvfuWXnuG5"><p>Cover image</p></div><p><span class="mark-grey"><em>Whether you listen or not: 1: The distorted binary numbers stuffed into the left side spell Hello World when converted to decimal and then ASCII. 2: The small English text under “Strongest AIC” means maximum Stock Bill output. 3: I pasted arrows onto the yellow strip on the left to pretend it was a belt. —盒猫</em></span></p><p><span id="source-block-JHB9yrgA7h2xtO0t0QlxBz"></span></p><h2 id="script-draft-02-2026-09-20-23-26" tabindex="-1">Script Draft 02 (2026.09.20 23:26) <a class="header-anchor" href="#script-draft-02-2026-09-20-23-26" aria-label="Permalink to &quot;Script Draft 02 (2026.09.20 23:26)&quot;">​</a></h2><p><span id="source-block-mmdylS8XHjIFfm2cfDiV6w"></span></p><h3 id="_0-why-automatic-production-balancing" tabindex="-1">0. Why Automatic Production Balancing? <a class="header-anchor" href="#_0-why-automatic-production-balancing" aria-label="Permalink to &quot;0. Why Automatic Production Balancing?&quot;">​</a></h3><p>At the beginning of version 1.4, gas industry brought us two great lords:</p><p><strong>&lt;（°0°）&gt;</strong><span class="mark-red"><strong>Lord Pyrrolite</strong></span>** and <strong><span class="mark-green"><strong>Lord Heavy Xiranite</strong></span></strong>\\（°0°）/**</p><p>My goodness, <span class="mark-red">Lord Pyrrolite</span> sells for 70 Stock Bills! Its extraordinarily complicated processing is mind-blowing!</p><p>[Visual: a mysterious passage of long, difficult sentences demonstrating the complexity of Pyrrolite processing]</p><p>After all sorts of video creators worked their mathematical magic,</p><p>we now know that maximum production capacity means making lots of <span class="mark-red">Lord Pyrrolite</span> and <span class="mark-green">Lord Heavy Xiranite</span>, plus two dignitaries from the previous dynasty: <span class="mark-orange">Lord SC Wuling Battery</span> and <span class="mark-blue">Yazhen Syringe [C]—er, the lowly servant</span>.</p><p>Ideally, not a scrap of <span class="mark-red">Cuprium</span> or <span class="mark-green">Xiranite</span> should remain, and the same goes for <span class="mark-orange">Originium Ore</span> and <span class="mark-blue">Ferrium</span>.</p><p>To achieve this, creators first proposed a balanced combination of 14.4 <span class="mark-red">Pyrrolite Parts</span> and 24 <span class="mark-green">Heavy Xiranite</span>, then an even more extreme combination of 14.2 <span class="mark-red">Pyrrolite Parts</span> and 26 <span class="mark-green">Heavy Xiranite</span>. The latter is already very, very close to the theoretical solution!</p><p>Uh, but I am just an ordinary player. Rather than squeeze out every last bit of production, I want to ask:</p><p>[Spoken]</p><p>What if I need medicine?</p><p>What if I have not unlocked all the mines?</p><p>What if I do not want to connect a Purification Node?</p><p>What if I have not unlocked over-capacity transfer in the Valley?</p><p>[Visual]</p><p><strong>What if all the inputs are balanced away and nothing is left to make the Yazhen Syringe [A] I need myself?</strong></p><p><strong>What if my mines are not all unlocked and cannot supply the line?</strong></p><p><strong>What if I do not want to connect a Purification Node—someone else can lay that blasted conduit—but maximum production requires it?</strong></p><p><strong>My Valley setup is not maxed out; I have no over-capacity transfer...</strong></p><p>Hey, an ordinary player with all these demands? Why not use a lower-output line that leaves more inputs over?</p><p>So what? I want to use all my inputs, get high output, and satisfy all these requirements. Is that not allowed?</p><p><strong>And so, through our efforts, automatically balanced production lines were born.</strong></p><hr><p><span id="source-block-1faCu7aoIRuLPFVhDwffDu"></span></p><h3 id="_1-local-automatic-production-balancing" tabindex="-1">1. Local Automatic Production Balancing <a class="header-anchor" href="#_1-local-automatic-production-balancing" aria-label="Permalink to &quot;1. Local Automatic Production Balancing&quot;">​</a></h3><p>Understanding how four inputs automatically balance into four products right away is too difficult. Let us first make only Pyrrolite and Heavy Xiranite.</p><p>[Visual: first show the complicated recipes for Pyrrolite Parts and Heavy Xiranite]</p><p>Although the recipes for <span class="mark-red">Pyrrolite Parts</span> and <span class="mark-green">Heavy Xiranite</span> are complicated, do not let them scare you. Ultimately, they use the same two inputs: <span class="mark-red"><strong>Cuprium</strong></span> and <span class="mark-green"><strong>Xiranite</strong></span>.</p><p>Let us ignore the twists and turns in between.</p><p>[Animation: fade out the complicated recipes, leaving only a simplified diagram, “Cuprium + Xiranite → Pyrrolite / Cuprium + Xiranite → Heavy Xiranite”]</p><p>Now imagine an account like this:</p><ul><li><p><span class="mark-red">Cuprium</span> output: <u><strong>325</strong></u>/min;</p></li><li><p><span class="mark-green">Xiranite and Xiragen</span> output maxed out;</p></li></ul><p>[Visual: show Cuprium and Xiranite as a bar chart, as below, with a mock report]</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-94b783219ced502b.q90-80a1cacb3b1a20ca.webp" alt="Explanation: Automatically Balanced Production Lines and Adaptive Devices"></p><p>We make only <span class="mark-red">Pyrrolite</span> and <span class="mark-green">Heavy Xiranite</span>. The output now looks like this:</p><p>[Animation: express the Pyrrolite/Heavy Xiranite balance with a bar chart and mock report. First hide the Xiranite and Cuprium icons in the image above, then overlay the image below]</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-242b204df8c9af15.q90-e688fb355386c397.webp" alt="Explanation: Automatically Balanced Production Lines and Adaptive Devices"></p><p>Now connect all the remaining mines, raising <span class="mark-red">Cuprium</span> output to 510/min.</p><p>[Animation: outline the newly added Cuprium in the bar chart with a dashed box]</p><p>How do we consume this extra <span class="mark-red">Cuprium</span>? If we increase <span class="mark-green">Heavy Xiranite</span> output,</p><p><span class="mark-grey">Invented data: 325 Xiranite, 325 Cuprium</span></p><p>[Animation: keep the Heavy Xiranite bar highlighted. Raise it and lower the Pyrrolite bar. Throughout, the Xiranite bar stays completely occupied, and the Cuprium bar naturally decreases]</p><p>Wait, no, no—why are we consuming even less <span class="mark-red">Cuprium</span>?! What if we increase <span class="mark-red">Pyrrolite</span> output instead?</p><p>[Animation: keep the Pyrrolite bar highlighted. Raise it and lower the Heavy Xiranite bar. Throughout, the Xiranite bar stays completely occupied, and the Cuprium bar naturally grows until it fills the dashed area representing the extra Cuprium]</p><p>Yes, that is it! Now all the extra <span class="mark-red">Cuprium</span> is consumed.</p><p><strong>In other words, to balance the extra <strong><span class="mark-red"><strong>Cuprium</strong></span></strong>, <strong><span class="mark-red"><strong>Pyrrolite</strong></span></strong> output must rise, while <strong><span class="mark-green"><strong>Heavy Xiranite</strong></span></strong> output falls accordingly. (Consider giving this its own screen.)</strong></p><p>[Animation: use a lighter color to highlight the original lengths of the Pyrrolite and Heavy Xiranite bars on the current chart for comparison. Time the highlights to “Pyrrolite output must rise” and “Heavy Xiranite output falls accordingly”]</p><p>But automatic balancing requires the line to increase <span class="mark-red">Pyrrolite</span> output and reduce <span class="mark-green">Heavy Xiranite</span> output by itself as <span class="mark-red">Cuprium</span> increases.</p><p>How can we do that? Here is the conclusion first:</p><p>[Consider giving these two sentences their own screen] [Or use an animation showing this feeding order]</p><ul><li><p><span class="mark-green"><strong>Xiranite</strong></span><strong>: satisfy the <strong><span class="mark-red"><strong>Pyrrolite line</strong></span></strong> first, then give the remainder to the <strong><span class="mark-green"><strong>Heavy Xiranite line</strong></span></strong>.</strong></p></li><li><p><span class="mark-red"><strong>Cuprium</strong></span><strong>: satisfy the <strong><span class="mark-green"><strong>Heavy Xiranite line</strong></span></strong> first, then give the remainder to the <strong><span class="mark-red"><strong>Pyrrolite line</strong></span></strong>.</strong></p></li></ul><hr><p><span id="source-block-UZH2II0Mn5LYYrBxTMtjDT"></span></p><h3 id="_2-the-feeding-order-cannot-be-reversed" tabindex="-1">2. The Feeding Order Cannot Be Reversed <a class="header-anchor" href="#_2-the-feeding-order-cannot-be-reversed" aria-label="Permalink to &quot;2. The Feeding Order Cannot Be Reversed&quot;">​</a></h3><p>Why must “<span class="mark-green">Xiranite</span> satisfy the <span class="mark-red">Pyrrolite line</span> first, and <span class="mark-red">Cuprium</span> satisfy the <span class="mark-green">Heavy Xiranite line</span> first”? Let us look at them one by one.</p><p><span id="source-block-jpwYyc2eYmxphzWFQvcrCp"></span></p><h4 id="if-the-pyrrolite-line-lacks-xiranite" tabindex="-1">If the <span class="mark-red">Pyrrolite line</span> lacks <span class="mark-green">Xiranite</span> <a class="header-anchor" href="#if-the-pyrrolite-line-lacks-xiranite" aria-label="Permalink to &quot;If the &lt;span class=&quot;mark-red&quot;&gt;Pyrrolite line&lt;/span&gt; lacks &lt;span class=&quot;mark-green&quot;&gt;Xiranite&lt;/span&gt;&quot;">​</a></h4><p>Return to the previous example, just after the mines were connected:</p><p>[Visual: the bar chart with the extra Cuprium outlined by a dashed box]</p><p>We try to increase <span class="mark-red">Pyrrolite</span> output, but there is not enough <span class="mark-green">Xiranite</span>. The increase stalls halfway!</p><p>[Animation: keep the Pyrrolite bar highlighted. Raise it and lower the Heavy Xiranite bar. Throughout, the Xiranite bar stays completely occupied, and the Cuprium bar naturally increases, but stops halfway. Flash the Pyrrolite portion of the Xiranite bar red to show insufficient supply]</p><p>We can now see that not all the extra <span class="mark-red">Cuprium</span> has been consumed.</p><p>[Animation: the Cuprium bar does not fill the dashed area. Flash the remaining dashed area red to show that it has not been consumed/fully used]</p><p><strong>Thus we conclude: to use the extra <strong><span class="mark-red"><strong>Cuprium</strong></span></strong>, we must first satisfy the <strong><span class="mark-red"><strong>Pyrrolite line</strong></span></strong> with <strong><span class="mark-green"><strong>Xiranite</strong></span></strong>, ensuring it has enough <strong><span class="mark-green"><strong>Xiranite</strong></span></strong>.</strong></p><p><span id="source-block-BJVYySQVQWYcEh1CFYZE7H"></span></p><h4 id="if-the-heavy-xiranite-line-lacks-cuprium" tabindex="-1">If the <span class="mark-green">Heavy Xiranite line</span> lacks <span class="mark-red">Cuprium</span> <a class="header-anchor" href="#if-the-heavy-xiranite-line-lacks-cuprium" aria-label="Permalink to &quot;If the &lt;span class=&quot;mark-green&quot;&gt;Heavy Xiranite line&lt;/span&gt; lacks &lt;span class=&quot;mark-red&quot;&gt;Cuprium&lt;/span&gt;&quot;">​</a></h4><p>Similarly, increase <span class="mark-green">Xiranite</span>, then try to increase <span class="mark-green">Heavy Xiranite</span> output.</p><p>[Animation: keep the Heavy Xiranite bar highlighted. Raise it and lower the Pyrrolite bar. Throughout, the Cuprium bar stays completely occupied, and the Xiranite bar naturally increases, but stops halfway. Flash the Heavy Xiranite portion of the Cuprium bar red to show insufficient supply]</p><p>The result is similar: because the <span class="mark-green">Heavy Xiranite line</span> lacks <span class="mark-red">Cuprium</span>, we have not used up the extra <span class="mark-green">Xiranite</span>.</p><p>[Animation: flash the remaining dashed area of the Xiranite bar red to show that it has not been consumed/fully used]</p><p>This is very similar to the <span class="mark-red">Pyrrolite line</span> lacking <span class="mark-green">Xiranite</span>. To use the extra <span class="mark-green">Xiranite</span>, we must first satisfy the <span class="mark-green">Heavy Xiranite line</span> with <span class="mark-red">Cuprium</span>, ensuring it has enough <span class="mark-red">Cuprium</span>.</p><p>[Visual: the conclusion from the previous section, <a href="/endfield-skydoc/explanation-automatically-balanced-production-lines-and-adaptive-devices">Explanation: Automatically Balanced Production Lines and Adaptive Devices</a>]</p><p>We have now answered why “<span class="mark-green">Xiranite</span> must satisfy the <span class="mark-red">Pyrrolite line</span> first, and <span class="mark-red">Cuprium</span> the <span class="mark-green">Heavy Xiranite line</span> first.” But another part of our conclusion remains: “give the remaining <span class="mark-green">Xiranite</span> to the <span class="mark-green">Heavy Xiranite line</span>, and the remaining <span class="mark-red">Cuprium</span> to the <span class="mark-red">Pyrrolite line</span>.”</p><p>[Visual: a chart with only the Heavy Xiranite bar; the unused Cuprium area is still a dashed box]</p><p>Suppose we make only <span class="mark-green">Heavy Xiranite</span>. The <span class="mark-green">Heavy Xiranite line</span> obviously cannot use this much <span class="mark-red">Cuprium</span> by itself.</p><p>[Animation: highlight the dashed unused portion of the Cuprium bar]</p><p>The <span class="mark-red">Pyrrolite line</span> must consume this remaining <span class="mark-red">Cuprium</span>.</p><p>[Animation: a Pyrrolite bar appears and grows until the Cuprium bar is filled]</p><p>Clearly, to use all the inputs completely, we need a line to consume the remainder.<br> For convenience, we call a line specifically consuming “a particular input left over by other lines” a:</p><p><strong>terminal production line (<strong>consider giving this its own screen</strong>)</strong></p><p>The <span class="mark-red">Pyrrolite line</span> can therefore be called the terminal line for the input <span class="mark-red">Cuprium</span>: the <span class="mark-red">Pyrrolite line</span> is the very last line among those consuming <span class="mark-red">Cuprium</span>.</p><p>[Visual: a chart with only the Pyrrolite bar; the unused Xiranite area remains a dashed box]</p><p>Likewise, the <span class="mark-green">Heavy Xiranite line</span> consumes the <span class="mark-green">Xiranite</span> left over when making only <span class="mark-red">Pyrrolite</span>. The <span class="mark-green">Heavy Xiranite line</span> can therefore be called the terminal line for <span class="mark-green">Xiranite</span>.</p><p>[Animation: a Heavy Xiranite bar appears and grows until the Xiranite bar is filled]</p><hr><p><span id="source-block-4QOXSXxHhkUYMnNs9qh1dD"></span></p><h3 id="_3-more-inputs" tabindex="-1">3. More Inputs!? <a class="header-anchor" href="#_3-more-inputs" aria-label="Permalink to &quot;3. More Inputs!?&quot;">​</a></h3><p>[Visual: the original Cuprium/Xiranite chart, with Originium Ore and Ferrium added to the axes]</p><p>So far, we have handled two inputs, <span class="mark-green"></span><span class="mark-red">Cuprium </span><span class="mark-green">Xiranite </span>, and two products, <span class="mark-red">Pyrrolite </span><span class="mark-green">Heavy Xiranite</span>.</p><p>But in version 1.5 we have two more inputs, <span class="mark-orange">Originium Ore</span> <span class="mark-blue">Ferrium </span>, and two more products, <span class="mark-blue"></span><span class="mark-orange">SC batteries</span><span class="mark-blue"> syringes</span>. (Add small labels: Yazhen Syringe over “syringes,” SC Wuling Battery over “SC batteries.”)</p><p>Now add them:</p><p>[Animation: expand “Cuprium, Xiranite → Pyrrolite, Heavy Xiranite” into “Cuprium, Xiranite, Originium Ore, Ferrium → Pyrrolite, Heavy Xiranite, SC batteries, syringes”]</p><p>Suddenly dizzy? Do not rush. Remember, our aim is to consume every input, so each input needs a line to use the portion left by the others. <strong>In other words, we can assign one terminal to each input!</strong></p><p>Attentive viewers may already have noticed that we use specific colors for inputs and products. Matching colors actually identify each input and its corresponding terminal:</p><p><span class="mark-red">Cuprium–Pyrrolite </span><span class="mark-green">Xiranite–Heavy Xiranite </span><span class="mark-orange">Originium Ore–SC batteries </span><span class="mark-blue">Ferrium–syringes</span></p><p>We already know that the <span class="mark-red">Pyrrolite line</span>, primarily consuming <span class="mark-red">Cuprium</span>, is the terminal line for <span class="mark-red">Cuprium input</span>, and the <span class="mark-green">Heavy Xiranite line</span>, primarily consuming <span class="mark-green">Xiranite</span>, is the terminal line for <span class="mark-green">Xiranite input</span>.</p><p>Then the <span class="mark-orange">SC battery line</span>, primarily consuming <span class="mark-orange">Originium Ore</span>, is the terminal line for <span class="mark-orange">Originium Ore input</span>, and the <span class="mark-blue">syringe line</span>, primarily consuming <span class="mark-blue">Ferrium</span>, is the terminal line for <span class="mark-blue">Ferrium input</span>!</p><p>[Visual: highlight the battery and syringe bars in turn as they are explained]</p><p>Just as with <span class="mark-red">Pyrrolite</span> and <span class="mark-green">Heavy Xiranite</span>, for the <span class="mark-orange">battery line</span> to consume all the <span class="mark-orange">Originium Ore</span> and the syringe line to consume all the Ferrium, we need the <span class="mark-orange">battery line</span> fully supplied with every input other than <span class="mark-orange">Originium Ore</span>. In other words, its <span class="mark-green">Xiranite</span> and Ferrium must be satisfied first.</p><p>[Animation: highlight the battery portions of the Xiranite and Ferrium bars]</p><p>The <span class="mark-blue">syringe line</span> consumes only <span class="mark-blue">Ferrium</span>, so it has no other input needing full supply.</p><p>We can organize this into a table:</p><table tabindex="0"><thead><tr><th>Input</th><th>Satisfy first</th><th>Give remainder to</th><th>Terminal</th></tr></thead><tbody><tr><td><span class="mark-red">Cuprium</span></td><td><span class="mark-green">Heavy Xiranite</span></td><td><span class="mark-red">Pyrrolite</span></td><td><span class="mark-red">Pyrrolite</span></td></tr><tr><td><span class="mark-green">Xiranite</span></td><td><span class="mark-red">Pyrrolite </span><span class="mark-orange">SC batteries</span></td><td><span class="mark-green">Heavy Xiranite</span></td><td><span class="mark-green">Heavy Xiranite</span></td></tr><tr><td><span class="mark-orange">Originium Ore</span></td><td>None</td><td><span class="mark-orange">SC batteries</span></td><td><span class="mark-orange">SC batteries</span></td></tr><tr><td><span class="mark-blue">Ferrium</span></td><td><span class="mark-orange">SC batteries</span></td><td><span class="mark-blue">syringes</span></td><td><span class="mark-blue">syringes</span></td></tr></tbody></table><hr><p><span id="source-block-WL13fhHXFTCR8WbVOO0loD"></span></p><h3 id="_4-more-varied-terminals" tabindex="-1">4. More Varied Terminals <a class="header-anchor" href="#_4-more-varied-terminals" aria-label="Permalink to &quot;4. More Varied Terminals&quot;">​</a></h3><p>[Visual: Cuprium, Xiranite, Originium Ore, Ferrium → Pyrrolite, Heavy Xiranite, SC batteries, syringes]</p><p>Must a terminal be a single product? Of course not!</p><p>For example, in the 1.5 automatic maximum-gross-output setup, while <span class="mark-red">Hetonite</span> storage is not full, <span class="mark-red">Hetonite</span> and <span class="mark-red">Pyrrolite</span> output stays at 1:2. The <span class="mark-red">Cuprium terminal</span> is then not simply <span class="mark-red">Pyrrolite</span>, but <span class="mark-red">“</span><span class="mark-red"><strong>Hetonite and Pyrrolite at 1:2”</strong></span><strong>.</strong></p><p>[Animation: replace the Pyrrolite Part icon with a combined Hetonite Part/Pyrrolite Part icon]</p><p>We can regard a terminal combining several products as the product of a custom recipe. It then works just like the single-product terminals above.</p><p>Introducing combined products as terminals gives us more kinds of products! Perhaps at the end of this road lies the ultimate <strong>all-item automatic balancing</strong>...</p><hr><p><span id="source-block-mA63XxzuxdkTwf9hxAfQO5"></span></p><h3 id="_5-recap" tabindex="-1">5. Recap <a class="header-anchor" href="#_5-recap" aria-label="Permalink to &quot;5. Recap&quot;">​</a></h3><p>[Visual: Cuprium, Xiranite, Originium Ore, Ferrium → Pyrrolite, Heavy Xiranite, SC batteries, syringes] (Or fade it into the background?)</p><p>Let us organize what we have covered:</p><p>For the whole automatic-balancing system, remember just two points: (consider letting these two lines fill the screen)</p><ol><li><p>Each input has a corresponding terminal: <span class="mark-red">Cuprium</span> corresponds to <span class="mark-red">Pyrrolite</span>, which can consume all the <span class="mark-red">Cuprium</span>, and <span class="mark-green">Xiranite</span> corresponds to <span class="mark-green">Heavy Xiranite</span>, which can consume all the <span class="mark-green">Xiranite</span>. A terminal may also combine products, such as <span class="mark-red">“Hetonite and Pyrrolite at 1:2”</span> serving as the <span class="mark-red">Cuprium terminal</span> in the preceding section.</p></li><li><p>Each input first satisfies the other lines using that input; only the remainder goes to its terminal. For example, <span class="mark-red">Cuprium</span> first satisfies the <span class="mark-green">Heavy Xiranite line</span>, ensuring that it can consume all the <span class="mark-green">Xiranite</span>. The remaining <span class="mark-red">Cuprium</span> then goes to the <span class="mark-red">Pyrrolite line</span>, the <span class="mark-red">Cuprium terminal</span>. In the five Chinese characters “<strong>先供非末端</strong>”: <strong>supply non-terminals first</strong>. We will repeatedly use those five characters in future explanations of automatic balancing.</p></li></ol><p>(Separator Cores, as an intermediate, make things somewhat more complex. We decided to put the written explanation in the description and may make a dedicated explanation video later.)</p><p><span class="mark-grey">#言: An explanation of Separator Cores for the description:<br> From this video, we can say that neither Pyrrolite nor Heavy Xiranite can consume all its Cuprium/Xiranite if another input is short. Treat Separator Cores as a special input, then: naturally, sufficient Separator Cores are needed for Pyrrolite/Heavy Xiranite to consume all the Cuprium/Xiranite. We need not think about what Separator Cores are made from—or do we?<br> With the current recipes, we can indeed treat it that way. But readers willing to come to the description probably want more than this rough explanation, so let me modify the Heavy Xiranite recipe slightly to make the statement fail:<br> (Original recipe) Xiranite + Separator Core → (modified recipe) Cuprium + Separator Core.<br> If we now freely supply Heavy Xiranite production with Separator Cores, it competes directly for them with the Pyrrolite line. If Heavy Xiranite takes too many, Pyrrolite becomes constrained by the reduced Separator Core supply and cannot consume the Cuprium left over by other lines. (Interestingly, taking too few Separator Cores means Pyrrolite receives enough. In other words, satisfy Pyrrolite&#39;s Separator Cores first, then let Heavy Xiranite consume the remainder. Heavy Xiranite becomes the Separator Core terminal, and Separator Cores become the Xiranite terminal—equivalent to Heavy Xiranite correctly serving as the Xiranite terminal.) Fundamentally, Heavy Xiranite has not correctly served as the Xiranite terminal here. One correct approach is therefore to supply the Heavy Xiranite line with Xiranite left over by other lines and sufficient Cuprium, rather than with Separator Cores, incorporating production of its Separator Cores into the Heavy Xiranite line itself.<br> In any case, remember that automatic balancing works because terminal lines correctly fulfill their terminal roles. This conclusion broadly follows the mathematics. Keeping Separator Cores sufficiently supplied or coupling their production into a terminal line are merely ways to make an actual line obey “supply non-terminals first” in different situations. (Yes, the solution in my example is not the only option.)<br> If you have read this far, you probably understand why the video did not explain Separator Cores as an intermediate—it does get dizzying. Yet they cannot be avoided in concrete line design. We put this text in the description in the hope it helps you understand/design automatic balancing yourself (heart hands). (Kids, do not believe that; the team simply procrastinated on the “Intermediates and Automatic Balancing” explanation video.) (What if, just what if, we really find the time to make it?)</span></p><p><span class="mark-grey"># An explanation of Separator Cores for the description (ko鸟&#39;s short version):</span></p><ol><li><p><span class="mark-grey">Separator Cores are not a product ultimately sold, so giving Cuprium and Xiranite to Separator Core production first and filling storage with them is certainly a valid approach. Why?</span></p></li><li><p><span class="mark-grey">When Separator Core storage is full, its quantity remains constant. The Separator Cores consumed by Pyrrolite and Heavy Xiranite therefore “pass through” directly and equivalently as Xiranite and Cuprium consumption. The whole problem then reduces to directly balancing Cuprium and Xiranite against Pyrrolite and Heavy Xiranite.</span></p></li><li><p><span class="mark-grey">Then apply what the video taught.</span></p></li></ol><p>[Visual: thumbnails of three production-line videos and an ellipsis]</p><p>“<strong>Supply non-terminals first</strong>” is the iron rule of automatic balancing. Our production-line explanation videos will demonstrate how different layouts implement it: empty storage–oversupply in the 1.5 video (highlight the 1.5 thumbnail here), and empty storage–direct connection/full storage–overflow/full storage–oscillation in the two 1.6 videos (highlight the two 1.6 thumbnails here). Stay tuned.</p><p><span class="mark-grey">#This does not mean we need to rush out the 1.6 thumbnails; white text on a black background can stand in for them.</span></p><p><span class="mark-grey">#(If using the simplified sixth section) “<strong>Supply non-terminals first</strong>” is the iron rule of automatic balancing. Next, we will implement it with actual in-game structures.</span></p><hr><p><span id="source-block-kqVBhL14xHrfvLosPFsx1U"></span></p><h3 id="_6-back-to-actual-production-lines-discarded" tabindex="-1"><span class="mark-grey">6. Back to Actual Production Lines (Discarded)</span> <a class="header-anchor" href="#_6-back-to-actual-production-lines-discarded" aria-label="Permalink to &quot;&lt;span class=&quot;mark-grey&quot;&gt;6. Back to Actual Production Lines (Discarded)&lt;/span&gt;&quot;">​</a></h3><p><span class="mark-grey"><strong>盒猫&#39;s version follows:</strong></span></p><p><strong>1. Oversupplying with Depot Unloaders</strong></p><p>How do we achieve this?</p><p>Start with oversupply: add extra Depot Unloaders to a line.</p><p>Take the Pyrrolite line in the version 1.5 maximum-gross-output setup.</p><p>First, review what we just learned:</p><p>The <span class="mark-red">Pyrrolite line </span>is not the terminal for <span class="mark-green">Xiranite</span>, so the <span class="mark-green">Xiranite</span> used by the <span class="mark-red">Pyrrolite line</span> receives priority.</p><p>[Show oversupply for Liquid Xiranite in the Pyrrolite line]</p><p>[Box the Xiranite oversupply section of the Pyrrolite line]</p><p>Version 1 here: we add extra Depot Unloaders to the module supplying Liquid Xiranite to the Pyrrolite line, to keep it running at full rate as far as possible.</p><p>Version 2 here: the module supplying Liquid Xiranite to the Pyrrolite line needs 30/min Xiranite for full-rate operation. If production is sufficient, one Xiranite Depot Unloader meets this requirement. With empty storage, however, one Unloader cannot meet the 30/min requirement, so we can add extra Unloaders to keep this module at full rate as far as possible. This implements priority Xiranite supply through oversupply from Depot Unloaders.</p><p>The same applies elsewhere.</p><p>For example, still in the Pyrrolite line, we can oversupply Xiranite to the Separator Core section in the same way.</p><p>[Show Xiranite oversupply for the Separator Core line]</p><p>[Same animation as above]</p><p>In the Heavy Xiranite line, because</p><p>“the <span class="mark-green">Heavy Xiranite line</span> is not the terminal for <span class="mark-red">Cuprium</span>, the <span class="mark-red">Cuprium</span> used by the <span class="mark-green">Heavy Xiranite line</span> receives priority,”</p><p>we need to oversupply Cuprium to the Separator Core section.</p><p>[Show Cuprium oversupply for the Separator Core line]</p><p>[Same animation as above]</p><p>In the SC Wuling Battery line, again, because</p><p><span class="mark-orange">“the SC Wuling Battery line</span> is not the terminal for <span class="mark-green">Xiranite</span> or <span class="mark-blue">Ferrium</span>, the <span class="mark-green">Xiranite</span> and <span class="mark-blue">Ferrium</span> used by the <span class="mark-orange">battery line</span> receive priority,”</p><p>we need to oversupply Xiranite to the Xircon section (a material needed for batteries—label this in the video <span class="mark-grey">(to keep any little geniuses from getting dizzy)</span>) and Ferrium Ore to the Ferrium Powder line.</p><p>[Show Xiranite oversupply for the Xircon line] [Show Ferrium Ore oversupply for Ferrium shredding]</p><p>The <span class="mark-blue">syringe line</span> needs no other input besides <span class="mark-blue">Ferrium</span>, so it is only the terminal for <span class="mark-blue">Ferrium</span> and receives no priority supply.</p><p>————————————————————————</p><p><strong>2. Overflow</strong></p><p>Besides oversupply, we can establish priorities with overflow routers.</p><p>For the principle, see this video (insert a link to 百亿&#39;s video).</p><p>————————————————————————</p><p>There are many, many other ways to achieve priority supply, such as full-storage overflow.</p><p><span class="mark-grey"><strong>言&#39;s version follows:</strong></span></p><p>(Visual: logging in) Now open the game and see how the actual line (斯改&#39;s strongest version 1.5 AIC) achieves automatic balancing. (Could these two sentences stay beside the visuals throughout the video? <a href="/endfield-skydoc/explanation-automatically-balanced-production-lines-and-adaptive-devices">Explanation: Automatically Balanced Production Lines and Adaptive Devices</a>):</p><ul><li><p>The Pyrrolite line is not the terminal for <span class="mark-green">Xiranite</span>, so the <span class="mark-green">Xiranite</span> used by the <span class="mark-red">Pyrrolite line</span> is satisfied first.<br> [Show oversupply for Liquid Xiranite in the Pyrrolite line and for Xiranite in the Separator Core line]<br><span class="mark-grey">Wait, why do more Depot Unloaders provide priority supply? (Show the Liquid Xiranite recipe.) An Expanded Crucible needs 30/min Xiranite (one every 2s) to produce Liquid Xiranite at full rate, while one Unloader outputs at most 30/min Xiranite (one every 2s). Here, two Unloaders connect to this one Expanded Crucible. Even if Xiranite use elsewhere keeps one Unloader below 30/min, they can still fully supply the 30/min the crucible needs. In other words,</span><span class="mark-grey"><strong>“</strong></span><strong>the <strong><span class="mark-green"><strong>Xiranite</strong></span></strong> used by the <strong><span class="mark-red"><strong>Pyrrolite line</strong></span></strong> is satisfied first</strong><span class="mark-grey"><strong>.”</strong></span></p></li><li><p>The <span class="mark-green">Heavy Xiranite line</span> is not the terminal for <span class="mark-red">Cuprium</span>, so the <span class="mark-red">Cuprium</span> used by the <span class="mark-green">Heavy Xiranite line</span> is satisfied first.<br> [Show Cuprium oversupply for the Separator Core line]</p></li><li><p>The <span class="mark-orange">battery line</span> is not the terminal for <span class="mark-green">Xiranite</span> or <span class="mark-blue">Ferrium</span>, so the <span class="mark-green">Xiranite</span> and <span class="mark-blue">Ferrium</span> used by the <span class="mark-orange">battery line</span> are satisfied first.<br> [Show Xiranite oversupply for the battery line and Ferrium oversupply for the Ferrium Powder line]</p></li><li><p>The <span class="mark-blue">syringe line</span> needs no other input besides <span class="mark-blue">Ferrium</span>, so it is only the terminal for <span class="mark-blue">Ferrium</span>, with nothing needing priority satisfaction.)</p></li></ul><p>Do not limit your thinking to adding Unloaders to guarantee priority supply with empty storage! There are many ways to achieve priority supply: (I think we could explain this in slightly more detail.)</p><p>Direct overflow from the Forge of the Sky to prioritize Xiranite; full-storage oscillation; oversupply one belt first and use its overflow; and approaches we have not covered...</p><p><span class="mark-grey"><strong>Zirunwang&#39;s version follows:</strong></span></p><p>How do we achieve our goal of “priority supply”?</p><p>When consumption exceeds output, the Unloaders take turns outputting, sharing the limited resources equally.</p><p>If two Unloaders are combined into one line, that line has twice the weight of the other output ports.</p><p>So just add a few more Unloaders to [these] lines!</p><hr><p><span id="source-block-2fr5Ewnj0NrSCQ63hqxmOR"></span></p><h3 id="_6-back-to-actual-production-lines-simplified-version" tabindex="-1"><span class="mark-grey">6. Back to Actual Production Lines (Simplified Version)</span> <a class="header-anchor" href="#_6-back-to-actual-production-lines-simplified-version" aria-label="Permalink to &quot;&lt;span class=&quot;mark-grey&quot;&gt;6. Back to Actual Production Lines (Simplified Version)&lt;/span&gt;&quot;">​</a></h3><p>Consider Ferrium first, the simplest case. The battery line and syringe line use Ferrium; the syringe line ensures that all Ferrium is consumed, so syringes are its terminal. We must first fully supply the <span class="mark-grey">(“</span>which is not the Ferrium terminal<span class="mark-grey">“ 盒: I feel this part can be omitted; it is a mouthful)</span> battery line.</p><p>Image: Ferrium Ore Depot Unloader → Refining Unit → powered Protocol Stash → Shredding Unit → Xircon → SC batteries; powered Protocol Stash → Ferrium Depot Unloader → syringes</p><p>Thus, only after the battery line has enough Ferrium will Ferrium overflow into the stash, enter the depot, and then become syringes.</p><p><span class="mark-grey">(Discarded) But this structure also causes trouble: Ferrium refining must connect to the battery line. Ferrium refining occupies little space and has a simple recipe, so that is not much of a problem. But the Xiranite line is that whole huge Forge of the Sky area.</span></p><p><span class="mark-grey">(Discarded) Xiranite has several non-terminal lines, meaning that both the Pyrrolite and battery lines must drag along a Forge of the Sky! That makes things very bulky, especially the already enormous Pyrrolite line, which must bring its whole family along and connect to the Forge. Is there a less miserable way? (Honestly, this seems a little off. To explain the bulkiness, we should explain that Xircon and battery production can be separated in the battery line, whereas almost every intermediate in the Pyrrolite line is liquid or gas and cannot be separated. But explaining the Pyrrolite line can easily drag us into explaining Separator Cores, which we worked so hard to skip. That would be awkward and add unnecessary mental load for beginners. At the same time, without explaining the bulkiness, viewers who know a little AIC but do not understand it deeply will wonder: why is it bulky, when Xircon production and battery production can clearly be separated? So I feel stuck at both ends.)</span></p><p>Of course, there are actually many ways to implement “supply xx first, then xx.” Our later production-line release videos will all explain “how to supply non-terminals first.” For example, we will later post an additional explanation of the “empty storage–oversupply” approach used in the familiar version 1.5 maximum-gross-output video (show the 1.5 maximum-gross-output thumbnail). The revised lines to be released later use “full storage–oscillation,” “full storage–overflow,” “empty storage–direct connection,” and “quantified Depot Unloaders” <span class="mark-grey">(Just say “more approaches”? 盒: I think naming these is fine. Normal viewers do not need to truly understand the terms here; they only need to know these things exist, without memorizing them, so there is no burden.)</span>. Explanation videos will accompany them. We hope viewers learn more AIC ideas from our designs and apply them to their own setups!</p><p><span id="source-block-ctjg208JA1DNTLwW4qG980"></span></p><h3 id="_7-why-can-you-add-your-own-lines" tabindex="-1">7. Why Can You Add Your Own Lines? <a class="header-anchor" href="#_7-why-can-you-add-your-own-lines" aria-label="Permalink to &quot;7. Why Can You Add Your Own Lines?&quot;">​</a></h3><p>Let us finish the video with something simple and relax.</p><p>Remember the “ordinary-player requirements” from the opening? [Show the corresponding clip]</p><p>Most of what we have covered concerns how an automatically balanced line balances itself. But if you manually add a new line, how does the balancing system handle its input consumption?</p><p>You can treat the inputs consumed by your additional line as never entering the automatic-balancing system, just like an unopened mine. Once that consumed portion is removed, the automatically balanced line converts all remaining inputs into the products we want.</p><p><strong>And that is how our extravagant wish to have everything comes true.</strong></p><p>But current automatic balancing still has limits. Let us leave this as a question:<br> How far can you go in adding your own lines—or at what input ratios will the automatically balanced line become unable to balance all remaining inputs?</p><p>(Wait 10s, then play the ending.)</p><hr><p>Ending:</p><p>That concludes our explanation of automatic balancing/adaptive production lines.</p><p>See you next time for “Adaptive Devices”!</p><p>[Visual: members&#39; signatures] (to be discussed)</p><p><span id="source-block-uSPzt91Tkj3UXVGuFFiNbE"></span></p><h2 id="script-draft-01-2026-09-20-14-44" tabindex="-1">Script Draft 01 (2026.09.20 14:44) <a class="header-anchor" href="#script-draft-01-2026-09-20-14-44" aria-label="Permalink to &quot;Script Draft 01 (2026.09.20 14:44)&quot;">​</a></h2><p><span class="mark-red">Pyrrolite</span><span class="mark-green">Heavy Xiranite</span><span class="mark-orange">SC batteries</span><span class="mark-blue">syringes</span></p><p><span class="mark-red">Cuprium</span><span class="mark-green">Xiranite</span><span class="mark-orange">Originium Ore</span><span class="mark-blue">Ferrium</span></p><p><span id="source-block-YxiPu1ktesxNu2Ai80cDnk"></span></p><h3 id="initial-explanation—local-automatic-balancing" tabindex="-1">Initial Explanation—Local Automatic Balancing <a class="header-anchor" href="#initial-explanation—local-automatic-balancing" aria-label="Permalink to &quot;Initial Explanation—Local Automatic Balancing&quot;">​</a></h3><p>Let us begin with the backbone of this adaptive AIC: balancing Cuprium and Xiranite through Pyrrolite Parts and Heavy Xiranite. (Perhaps include icons.)</p><p>Although the recipes for Pyrrolite Parts and Heavy Xiranite are complicated (show the original recipes), they essentially use Xiranite and Cuprium. (Insert animation: simplify the complex recipes into recipes using only Cuprium and Xiranite.)</p><p>To understand automatic balancing, begin with a simpler, more local situation: an account producing Cuprium at 360/min with Xiranite and Xiragen output maxed out. (Bring up its Cuprium/Xiranite bar chart.) Now connect the remaining mines to reach 510/min Cuprium. (Outline the newly opened Cuprium with a dashed box.) To balance this Cuprium, increase Pyrrolite output. (Flash the Cuprium/Xiranite used by Pyrrolite on the chart, or highlight them another way.) The extra Pyrrolite Parts consume more Xiranite (similarly highlight that Xiranite), while Heavy Xiranite output falls (similarly highlight its Cuprium/Xiranite). (Uh, could we put arrows at the boundaries when highlighting?) Ultimately, increasing Pyrrolite Parts and reducing Heavy Xiranite balances the extra Cuprium output. (Animate the chart from the old state to the new.)</p><p>How can the line spontaneously increase Pyrrolite output and decrease Heavy Xiranite output as Cuprium output rises? The conclusion first: Xiranite first ensures sufficient Xiranite supply to the Pyrrolite line, with the remainder going to the Heavy Xiranite line; Cuprium first ensures sufficient Xiranite supply to the Heavy Xiranite line, with the remaining Cuprium going to the Pyrrolite line.</p><p><span id="source-block-QOxgDyvlkq06FPNwl39jag"></span></p><h3 id="why-non-terminals-cannot-be-undersupplied-fully-supplying-non-terminals" tabindex="-1">Why Non-Terminals Cannot Be Undersupplied / Fully Supplying Non-Terminals <a class="header-anchor" href="#why-non-terminals-cannot-be-undersupplied-fully-supplying-non-terminals" aria-label="Permalink to &quot;Why Non-Terminals Cannot Be Undersupplied / Fully Supplying Non-Terminals&quot;">​</a></h3><p>Start with the Pyrrolite line. What if its Xiranite supply is insufficient? Return to the previous example: increase Pyrrolite and reduce Heavy Xiranite. (Highlight in sequence as above; uh, the details can be discussed later.) (The transition from old state to new stops halfway because Xiranite is insufficient.) Some Cuprium is unused! Similarly, imagine an account with Cuprium maxed out but Xiragen deposits not yet connected. What if we cannot guarantee enough Cuprium for Heavy Xiranite? (Animation similar to Pyrrolite.) Some Xiranite is unused. Thus, the more Cuprium-intensive Pyrrolite line needs sufficient Xiranite, and the more Xiranite-intensive Heavy Xiranite line needs sufficient Cuprium.</p><p><span id="source-block-BUsTuWsaMRCCb0IXWgrJ5q"></span></p><h3 id="not-fully-supplying-terminals-terminals-use-remaining-inputs" tabindex="-1">Not Fully Supplying Terminals / Terminals Use Remaining Inputs <a class="header-anchor" href="#not-fully-supplying-terminals-terminals-use-remaining-inputs" aria-label="Permalink to &quot;Not Fully Supplying Terminals / Terminals Use Remaining Inputs&quot;">​</a></h3><p>We have now covered half our initial conclusion: “Xiranite first ensures sufficient Xiranite supply to the Pyrrolite line, with the remainder going to the Heavy Xiranite line; Cuprium first ensures sufficient Xiranite supply to the Heavy Xiranite line, with the remaining Cuprium going to the Pyrrolite line.” What does giving the remaining Xiranite to Heavy Xiranite and remaining Cuprium to Pyrrolite mean? Start with the latter. Suppose we make no Pyrrolite, only Heavy Xiranite. (Chart with only Heavy Xiranite.) Much Cuprium remains unused. To use what Heavy Xiranite leaves, increase Pyrrolite and reduce Heavy Xiranite. (Corresponding animation.) In other words, all Cuprium beyond what the Heavy Xiranite line needs eventually flows to the Pyrrolite line! Similarly, suppose we make only Pyrrolite, then add Heavy Xiranite to use the remaining Xiranite. (Corresponding animation.) Once Pyrrolite has sufficient Xiranite, the remainder flows to the Heavy Xiranite line.</p><p><span id="source-block-XeOpz3nTAVJxnNSQ3EDvQV"></span></p><h3 id="more-terminal–input-pairs" tabindex="-1">More Terminal–Input Pairs <a class="header-anchor" href="#more-terminal–input-pairs" aria-label="Permalink to &quot;More Terminal–Input Pairs&quot;">​</a></h3><p>Now extend this principle to more inputs! (Animate Cuprium/Xiranite–Pyrrolite/Heavy Xiranite into Cuprium/Xiranite/Originium/Ferrium–Pyrrolite/Heavy Xiranite/batteries/syringes.) Dizzy already? It is still the same principle. Look at the newly added batteries and Yazhen Syringes. (Highlight them.) SC batteries use a lot of Originium Ore, so fully supply their other inputs—Xiranite and Ferrium—then let the remaining Originium Ore flow to them. Since Pyrrolite, Heavy Xiranite, and syringes use no Originium, all Originium Ore actually goes to batteries. Ferrium uses no other inputs, so it simply receives the remaining Ferrium. Each input corresponds to a product that uses what other products leave over; we call it the terminal. Here, Pyrrolite uses the Cuprium left by Heavy Xiranite, making Pyrrolite the Cuprium terminal; Heavy Xiranite uses Xiranite left by Pyrrolite and batteries, making it the Xiranite terminal; batteries are the Originium Ore terminal, and syringes the Ferrium terminal.</p><p><span id="source-block-5CseafpFcCFziil8eb2h90"></span></p><h3 id="more-complicated-terminals" tabindex="-1">More Complicated Terminals <a class="header-anchor" href="#more-complicated-terminals" aria-label="Permalink to &quot;More Complicated Terminals&quot;">​</a></h3><p>Must a terminal be a single product? Of course not! In the 1.5 automatic maximum-gross-output setup, before Hetonite storage is full, Pyrrolite/Hetonite output stays at 1:2; the Cuprium terminal is then Hetonite Parts and Pyrrolite Parts at 1:2. However, from the ticket-revenue perspective, this terminal is worth less than a purely Pyrrolite terminal.</p><p><span id="source-block-bN9YKhSGeOTZu3Yp5K1Mm5"></span></p><h2 id="module-explanations-from-the-original-video" tabindex="-1">Module Explanations from the Original Video <a class="header-anchor" href="#module-explanations-from-the-original-video" aria-label="Permalink to &quot;Module Explanations from the Original Video&quot;">​</a></h2><p><span id="source-block-SgLG4RYruAXSdwkboDc6uA"></span></p><h3 id="jingyu-valley" tabindex="-1">Jingyu Valley <a class="header-anchor" href="#jingyu-valley" aria-label="Permalink to &quot;Jingyu Valley&quot;">​</a></h3><p>This is the dual-core SC battery line. It consumes Xircon and Originium Ore to produce SC Wuling Batteries, and additionally recovers one belt of Sandleaf Powder, which the main base uses for the remaining half-rate batteries.</p><p>This is the Xiranite line. After water is connected, its Planting Unit loop produces enough plants to feed 12 Forges of the Sky making Xiranite.</p><p><span id="source-block-iUtARgwjRSvwMVlHrK4liC"></span></p><h3 id="main-base" tabindex="-1">Main Base <a class="header-anchor" href="#main-base" aria-label="Permalink to &quot;Main Base&quot;">​</a></h3><p>This is the remaining SC battery line. Besides Originium Ore, it consumes the belt of Sandleaf Powder recovered from Jingyu Valley&#39;s battery line and, if available, Dense Originium Powder from over-capacity transfer, producing SC Wuling Batteries.</p><p>This is the Cuprium refining line. It consumes Clean Water to refine Cuprium Ore into Cuprium and generates large quantities of Sewage.</p><p>This is the overflow-safe Xircon line with three Expanded Crucibles and one small Reactor Crucible. It takes sufficient Xiranite, Ferrium Powder, Sewage, and Liquid Xiranite to produce Xircon. Unlike the common four-Expanded-Crucible line or three-expanded/two-small line, we removed the Liquid Xiranite crucible and placed it with the Heavy Xiranite line&#39;s crucible to coordinate Liquid Xiranite supply centrally.</p><p>This is the Ferrium Powder line. Extra Depot Unloaders ensure sufficient Ferrium Powder inputs for the Xircon line even when Ferrium storage is empty.</p><p>This is the syringe line. It makes syringes from Ferrium left over by the Ferrium Powder line.</p><p>This is the oversupplied Separator Core line. Extra Unloaders ensure enough inputs to make Separator Cores even when Cuprium or Xiranite storage is empty.</p><p>This is the Xiranite liquefaction line. One crucible also produces the medicinal solution used for syringes.</p><p>This is the adaptive Xiragen line. It spontaneously stops production when Xiragen is sufficient to avoid wasting Liquid Xiranite, and uses adaptive oscillating supply to achieve 0 Liquid Xiranite waste for any Liquid Xiranite input rate.</p><p>This is the adaptive Heavy Xiranite line. Adaptive oscillating supply achieves 0 Xiragen waste for any Xiragen input rate.</p><p>This is the disposal module. Unlike common modules destroying final products, it destroys overflowing Sewage and Cuprium. When Cuprium storage fills, it destroys Cuprium to keep enough Sewage available for Xircon; when both battery and Xircon storage fill and the Xircon line&#39;s Sewage consumption drops sharply, it destroys overflowing Sewage to keep the adjacent Cuprium refining line operating normally.</p><p>This is the Pyrrolite gear-component line. Because Pyrrolite gear components can make equipment otherwise made with other gear components, other gear-component lines are unnecessary.</p><p>This is the Cuprium shredding line. Its Cuprium Powder becomes Pyrrolite Parts and Hetonite Parts at Yinglung Pass.</p><p><span id="source-block-jqE9qDVLl7hib7enWBjDYy"></span></p><h3 id="marker-stone" tabindex="-1">Marker Stone <a class="header-anchor" href="#marker-stone" aria-label="Permalink to &quot;Marker Stone&quot;">​</a></h3><p>Holds the oversupplied Separator Core, Cuprium refining, and Cuprium shredding lines that cannot fit at the main base because of insufficient water and Inergen.</p><p><span id="source-block-YkHPmnd7sMzC8RnByQFIqi"></span></p><h3 id="yinglung-pass" tabindex="-1">Yinglung Pass <a class="header-anchor" href="#yinglung-pass" aria-label="Permalink to &quot;Yinglung Pass&quot;">​</a></h3><p>This is the Cuprium liquefaction line. Two Expanded Crucibles also produce the Liquid Xiranite needed by the Cuprium Gas line.</p><p>This is the adaptive Cuprium Gas line. Adaptive oscillating supply achieves 0 Liquid Xiranite waste across a broad range of Cuprium Solution inputs. Perfect compression.</p><p>This is the Hetonite Gas line. In an Inergen environment, it uses Separator Cores to purify Cuprium Gas into Hetonite Gas.</p><p>This is the adaptive Pyrrolite Gas line with an oscillating acid environment. Adaptive oscillating supply minimizes acid-liquid input across a broad range of Hetonite Gas inputs, saving the Liquid Xiranite used to gasify that acid. The Fluid-Gas Transmuting Unit jointly producing Acridgen and Xiragen also uses adaptive oscillating supply for 0 Liquid Xiranite waste during their production.</p><p>This is the adaptive Hetonite/Pyrrolite line with automatic switching between the two. Adaptive oscillating supply achieves 0 Xiragen waste across a broad range of Hetonite Gas/Pyrrolite Gas inputs. When Hetonite storage fills, Hetonite blocks the liquid passing through an unpowered Reactor Crucible; that blocked liquid blocks Hetonite Gas input. With help from a residue-clearing device, the line then switches fully automatically from Hetonite to Pyrrolite production.</p><p><span id="source-block-xQZEb7EUWaqy0tuIq0oY9L"></span></p><h2 id="undecided-topics" tabindex="-1">Undecided Topics <a class="header-anchor" href="#undecided-topics" aria-label="Permalink to &quot;Undecided Topics&quot;">​</a></h2><p><span id="source-block-BwV0i64mm63Pdnc2Z3oOMH"></span></p><h2 id="copy-script-discussion" tabindex="-1">Copy/Script Discussion <a class="header-anchor" href="#copy-script-discussion" aria-label="Permalink to &quot;Copy/Script Discussion&quot;">​</a></h2><p><span id="source-block-1RyfHoAVpOrOvSjtMXeTLE"></span></p><h3 id="_2026-9-19-22-43" tabindex="-1">2026.9.19 22:43 <a class="header-anchor" href="#_2026-9-19-22-43" aria-label="Permalink to &quot;2026.9.19 22:43&quot;">​</a></h3><p>Framework:<br> What happens from old state to new (increased Cuprium)—show the iterative automatic-balancing process</p><p>↓</p><p>What happens with insufficient Xiranite—show why non-terminals need sufficient supply</p><p>↓</p><p>Expand the old-to-new transition (new old state: only Heavy Xiranite; new new state: add Pyrrolite until Cuprium/Xiranite balance)—emphasize that Pyrrolite uses remaining Cuprium</p><p><span id="source-block-JOxC2fD52yXIh4EYJhbbOd"></span></p><h3 id="_2026-9-14-20-58" tabindex="-1">2026.9.14 20:58 <a class="header-anchor" href="#_2026-9-14-20-58" aria-label="Permalink to &quot;2026.9.14 20:58&quot;">​</a></h3><p>For convenience, temporarily treat both Xiranite and Xiragen as Xiranite.</p><p>To understand automatic balancing, suppose an account has not maxed out Cuprium Ore, currently producing 420/min.</p><p>To maximize tickets, we turn Cuprium, Xiranite, Originium Ore, and Ferrium into Pyrrolite Parts, Heavy Xiranite, SC Wuling Batteries, and Yazhen Syringes.</p><p>First focus on how Pyrrolite Parts and Heavy Xiranite balance Cuprium and Xiranite.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7da7429867a00f86.q90-f9c4bbb4c26b2f9e.webp" alt="Explanation: Automatically Balanced Production Lines and Adaptive Devices"></p><p>Now open the mines: more Cuprium Ore! Solve a pair of linear equations in two variables to obtain the new balance.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-af74318dad62164e.q90-585d5891a6d704b1.webp" alt="Explanation: Automatically Balanced Production Lines and Adaptive Devices"></p><p>Pyrrolite increases and Heavy Xiranite decreases. But what if the Xiranite supplied to Pyrrolite Parts does not keep up with Pyrrolite&#39;s demand in the new balance?</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f58e31a95e24c60a.q90-5492ff1c8c0a945c.webp" alt="Explanation: Automatically Balanced Production Lines and Adaptive Devices"></p><p>It cannot balance completely; some Cuprium remains unused! So we must supply Pyrrolite with enough Xiranite.<br> How on earth can we visually express prioritizing Xiranite for Pyrrolite without fully supplying its Cuprium aaaaaah?</p><p>君: Think about it differently: incomplete Cuprium supply → supply the remaining Cuprium. Excess Xiranite injection lets the factory accept all remaining Cuprium. Treat it as the initial item that [activates the machine], rather than as a [reactant].</p><p>Production-line objective: take the old balance as initial state and new balance as final state. Initial Pyrrolite ＞ final Pyrrolite; initial Heavy Xiranite ＜ final Heavy Xiranite. This establishes the direction of demand changes through iteration.</p><p>Corresponding discrete iteration: Cuprium suddenly increases and must go to the Pyrrolite factory, which tries to consume more Xiranite. The Heavy Xiranite factory then receives less remaining Xiranite, reducing the corresponding Cuprium (Separator Core) consumption and increasing remaining Cuprium again. This completes one iteration and creates an intermediate state. The Pyrrolite factory receives remaining Cuprium again, repeating the same process to reduce remaining Cuprium gradually toward 0.</p><p>The corresponding continuous process is: Heavy Xiranite output gradually falls and Pyrrolite output gradually rises, clearly matching the required product changes from initial → final state.</p><p>Final convergence/divergence of products: we only need to explain that remaining Cuprium x tends to 0 as iteration count n tends to infinity. The process clearly shows x is an exponential function of n. Under the Xiranite and Heavy Xiranite priority settings for Pyrrolite and Heavy Xiranite, its base is less than 1; <s>the reader can easily prove this</s>. See automatic-balancing theory for details. (言: this hypothetical initial-to-final iteration can show convergence through visualization rather than a proof.</p><p>Because extra Cuprium must enter the Pyrrolite line, Cuprium cannot be oversupplied. Oversupplying Cuprium would prevent Heavy Xiranite from balancing Xiranite. We want Pyrrolite and Heavy Xiranite to compete for every unit of Cuprium and Xiranite. I feel the iteration should also be explained alongside the line.<br> The iteration means: more Cuprium, more Pyrrolite, less Xiranite, less Heavy Xiranite, a little more Cuprium again; repeat until all Cuprium and Xiranite are used and only Pyrrolite/Heavy Xiranite are produced. By conservation, we can regard their production as balancing Cuprium/Xiranite over sufficiently long periods.</p><p>I am crying from frustration.</p><p>Just visualize this iteration directly?</p><p>Then also visualize how the iteration behaves without sufficient Xiranite for Pyrrolite.</p><p><span id="source-block-hyzbWvKvqI97NgRfXUOfrk"></span></p><h3 id="_2026-9-17-1-23" tabindex="-1">2026.9.17 1:23 <a class="header-anchor" href="#_2026-9-17-1-23" aria-label="Permalink to &quot;2026.9.17 1:23&quot;">​</a></h3><p>言: Explain just two aspects? During old-to-new iteration, ① if Pyrrolite lacks Xiranite, it cannot consume all the Cuprium, leaving some over; likewise for Heavy Xiranite. ② With sufficient Xiranite, Pyrrolite consumes extra Cuprium; with sufficient Cuprium, Heavy Xiranite consumes extra Xiranite. Eventually both inputs are exhausted, and by conservation, consuming all Cuprium/Xiranite while producing only Pyrrolite/Heavy Xiranite clearly means successful balancing.<br> Then visualize these two processes.</p><blockquote><p>Translation notes: Draft 01 twice says that Cuprium guarantees the Heavy Xiranite line&#39;s “Xiranite supply”; this apparent input-name slip is preserved. Its final section reverses the named Pyrrolite/Hetonite ratio compared with Draft 02, and the discussion&#39;s initial/final inequalities conflict with its subsequent iteration description; these source inconsistencies are preserved. Chinese embedded in images has not been redrawn.</p></blockquote></div>',1)])])}const m=a(r,[["render",s]]);export{h as __pageData,m as default};
